SELECT url
FROM
    tb_screen_images
WHERE
    type = #{type}

    AND person_id = #{personId}


    AND screen_type = #{screenType}


    AND `year` = #{year}

ORDER BY screen_order DESC
LIMIT 1

SELECT id
FROM tb_screen_images
WHERE person_id = #{personId}
  AND type = #{imageType}
  AND screen_order = #{ screenOrder}
  AND year = #{ year}
  AND screen_type = #{ screenType}
  AND deleted = 0

SELECT id
FROM tb_screen_images
WHERE id_num=#{idNum}
    AND type = #{imageType}
    AND screen_order = #{ screenOrder}
    AND year = #{ year}
    AND screen_type = #{ screenType}
    AND deleted = 0
